// ValidateCreateTokenResponseBody runs the validations defined on
// Create-TokenResponseBody
func ValidateCreateTokenResponseBody(body *CreateTokenResponseBody) (err error) {
	if body.Secret == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("secret", "body"))
	}
	if body.Token == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("token", "body"))
	}
	if body.Token != nil {
		if err2 := ValidateTokenResponseResponseBody(body.Token); err2 != nil {
			err = goa.MergeErrors(err, err2)
		}
	}
	return
}

// ValidateListTokensResponseBody runs the validations defined on
// List-TokensResponseBody
func ValidateListTokensResponseBody(body *ListTokensResponseBody) (err error) {
	if body.Tokens == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("tokens", "body"))
	}
	for _, e := range body.Tokens {
		if e != nil {
			if err2 := ValidateTokenResponseResponseBody(e); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	return
}

// ValidateValidateTokenResponseBody runs the validations defined on
// Validate-TokenResponseBody
func ValidateValidateTokenResponseBody(body *ValidateTokenResponseBody) (err error) {
	if body.UID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("uid", "body"))
	}
	if body.Username == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("username", "body"))
	}
	if body.Audience == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("audience", "body"))
	}
	if body.UID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.uid", *body.UID, goa.FormatUUID))
	}
	if body.Audience != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.audience", *body.Audience, "^[a-z][a-z0-9-]{1,31}$"))
	}
	if body.Email != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.email", *body.Email, goa.FormatEmail))
	}
	return
}

