// ValidateTokenResponseResponseBody runs the validations defined on
// token-responseResponseBody
func ValidateTokenResponseResponseBody(body *TokenResponseResponseBody) (err error) {
	if body.UID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("uid", "body"))
	}
	if body.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "body"))
	}
	if body.Audience == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("audience", "body"))
	}
	if body.LookupID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("lookup_id", "body"))
	}
	if body.Username == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("username", "body"))
	}
	if body.CreatedAt == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("created_at", "body"))
	}
	if body.UID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.uid", *body.UID, goa.FormatUUID))
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 1, true))
		}
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) > 100 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 100, false))
		}
	}
	if body.Audience != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.audience", *body.Audience, "^[a-z][a-z0-9-]{1,31}$"))
	}
	if body.LookupID != nil {
		if utf8.RuneCountInString(*body.LookupID) < 12 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.lookup_id", *body.LookupID, utf8.RuneCountInString(*body.LookupID), 12, true))
		}
	}
	if body.LookupID != nil {
		if utf8.RuneCountInString(*body.LookupID) > 12 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.lookup_id", *body.LookupID, utf8.RuneCountInString(*body.LookupID), 12, false))
		}
	}
	if body.CreatedAt != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.created_at", *body.CreatedAt, goa.FormatDateTime))
	}
	if body.LastUsedAt != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.last_used_at", *body.LastUsedAt, goa.FormatDateTime))
	}
	return
}
